package app

import (
	"fmt"
	"strings"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
)

// minListHeight is the smallest usable viewport height that holds a list: one
// row and the bottom rule.
const minListHeight = 2

// noticeEmptyLine is the warning for an enter on a line with nothing typed.
const noticeEmptyLine = "Type a name or choose one"

// refreshSuggestions ranks the registry for the text in the command line. The
// first row is highlighted when a query is typed (a bare ":" is none) and
// something is found; otherwise nothing is, so enter cannot run a command nobody chose.
func (a *App) refreshSuggestions() {
	a.suggestions = a.suggester.Suggest(a.commandInput.Value())
	a.sugOffset = 0
	a.sugCursor = -1
	if a.argStage() {
		a.sugCursor = a.defaultArgCursor()
		return
	}
	if a.suggestions.Query != "" && len(a.suggestions.Entries) > 0 {
		a.sugCursor = 0
	}
}

// refreshSuggestionsKeepCursor recomputes the list after an asynchronous load
// without undoing a move the user already made: the cursor stays where it was,
// bounded to the new number of rows.
func (a *App) refreshSuggestionsKeepCursor() {
	cursor, offset := a.sugCursor, a.sugOffset
	a.refreshSuggestions()
	if cursor < 0 || a.sugCursor < 0 {
		return
	}
	a.sugCursor = min(cursor, a.listRowCount()-1)
	a.sugOffset = max(min(offset, a.sugCursor), 0)
}

// resetSuggestions forgets the list; the command line is closed or about to be
// reopened empty.
func (a *App) resetSuggestions() {
	a.suggestions = command.Suggestions{}
	a.sugCursor = -1
	a.sugOffset = 0
	a.sugNotice = ""
}

// highlightedEntry returns the highlighted row, if there is one. With no list
// drawn there is no highlight: a choice nobody can see is never made.
func (a *App) highlightedEntry() (command.Entry, bool) {
	if a.listVisible() == 0 || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Entries) {
		return command.Entry{}, false
	}
	return a.suggestions.Entries[a.sugCursor], true
}

// canComplete reports whether tab has something to complete: a highlighted
// row, at the command stage (an argument is typed, not chosen).
func (a *App) canComplete() bool {
	if a.argStage() {
		return a.listVisible() > 0 && len(a.suggestions.Args) > 0
	}
	_, ok := a.highlightedEntry()
	return ok && a.suggestions.Stage == command.StageCommand
}

// nothingToRunNotice is the warning for an enter with no highlighted row.
func (a *App) nothingToRunNotice() string {
	q := a.suggestions.Query
	if q == "" {
		return noticeEmptyLine
	}
	return fmt.Sprintf("%q is not a view or a command", q)
}

// completeHighlighted writes the highlighted row's name into the line, with a
// trailing space when the command takes an argument. It runs nothing.
func (a *App) completeHighlighted() {
	if a.argStage() {
		a.completeArg()
		return
	}
	if !a.canComplete() {
		return
	}
	entry, _ := a.highlightedEntry()
	text := entry.Name
	if entry.TakesArg() {
		text += " "
	}
	a.commandInput.SetValue(text)
	a.commandInput.CursorEnd()
	a.refreshSuggestions()
}

// listUsable is the number of viewport content lines the list may cover.
func (a *App) listUsable() int {
	if a.frameless() {
		return a.viewport.Height
	}
	return a.viewport.Height - 1 // the bottom border stays
}

// listVisible is how many suggestion rows are drawn; 0 means no list.
func (a *App) listVisible() int {
	usable := a.listUsable()
	if usable < minListHeight {
		return 0
	}
	return cmdsuggest.VisibleRows(a.listRowCount(), usable)
}

// moveHighlight moves the highlight by delta rows without wrapping. With no
// highlighted row, down takes the first visible row and up the last.
func (a *App) moveHighlight(delta int) {
	n := a.listRowCount()
	if n == 0 {
		return
	}
	visible := a.listVisible()
	switch {
	case a.sugCursor < 0 && delta > 0:
		a.sugCursor = a.sugOffset
	case a.sugCursor < 0:
		a.sugCursor = min(n-1, a.sugOffset+max(visible, 1)-1)
	default:
		a.sugCursor = max(min(a.sugCursor+delta, n-1), 0)
	}
	a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, visible)
}

// keepHighlightVisible re-windows the list after the viewport changed size.
func (a *App) keepHighlightVisible() {
	a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, a.listVisible())
}

// suggestionLines renders the list and its bottom rule, or nil when the command
// line is closed or the viewport is too short for a list.
func (a *App) suggestionLines() []string {
	visible := a.listVisible()
	if !a.commandMode || visible == 0 {
		return nil
	}
	rows := a.entryRows()
	var heading, empty string
	var loading bool
	if a.argStage() {
		rows = a.argRows()
		heading, empty = a.argHeading(), a.argEmpty()
		loading = !a.suggestions.ArgsReady
	}
	frame := cmdsuggest.FrameJoined
	if a.frameless() {
		frame = cmdsuggest.FrameClosed
	}
	return cmdsuggest.Render(cmdsuggest.Input{
		Rows:    rows,
		Total:   a.suggestions.Total,
		Query:   a.suggestions.Query,
		Cursor:  a.sugCursor,
		Offset:  a.sugOffset,
		Notice:  a.sugNotice,
		Heading: heading,
		Empty:   empty,
		Loading: loading,
		Width:   a.viewport.Width,
		Visible: visible,
		Frame:   frame,
	})
}

// entryRows renders the command-stage suggestions as list rows.
func (a *App) entryRows() []cmdsuggest.Row {
	rows := make([]cmdsuggest.Row, len(a.suggestions.Entries))
	for i, e := range a.suggestions.Entries {
		rows[i] = cmdsuggest.Row{Entry: e, Current: e.Kind == command.KindView && e.Name == string(a.currentView)}
	}
	return rows
}

// overlaySuggestions replaces the top lines of the viewport with the list.
// Whole lines are swapped, so no styled text is ever cut.
func (a *App) overlaySuggestions(body string) string {
	list := a.suggestionLines()
	if len(list) == 0 {
		return body
	}
	lines := strings.Split(body, "\n")
	copy(lines, list)
	return strings.Join(lines, "\n")
}
package app

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders the interface: header, title line, viewport, footer (Rule 124).
// An open overlay replaces the whole thing.
func (a *App) View() string {
	if overlay := a.activeOverlay(); overlay != "" {
		return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
	}

	header := a.renderHeader() + "\n" + a.renderTitleLine()
	body := a.renderBody()
	footer := a.renderViewFooter()
	inner := fitHeight(header, body, footer, a.height)

	return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
		lipgloss.WithWhitespaceBackground(theme.ColorBackground))
}

// fitHeight stacks header, body and footer in at most height lines.
// lipgloss.Place pads a short block but never crops a tall one, so on a very
// small terminal (header 10 + title 1 + the viewport's minimum + footer) the
// frame would be taller than the screen. The surplus is taken from the body
// first, bottom lines first: the header carries the command line and the
// footer carries the messages, so both outrank viewport rows. If the header
// alone is taller than the terminal, the whole stack is cut to its first
// height lines, the simplest floor. At normal heights nothing is cut.
func fitHeight(header, body, footer string, height int) string {
	parts := []string{header}
	if body != "" {
		parts = append(parts, body)
	}
	if footer != "" {
		parts = append(parts, footer)
	}
	lines := strings.Split(strings.Join(parts, "\n"), "\n")
	excess := len(lines) - height
	if height <= 0 || excess <= 0 {
		return strings.Join(lines, "\n")
	}

	headerLen := strings.Count(header, "\n") + 1
	bodyLen := 0
	if body != "" {
		bodyLen = strings.Count(body, "\n") + 1
	}
	cut := min(excess, bodyLen)
	if cut > 0 {
		end := headerLen + bodyLen
		lines = append(lines[:end-cut], lines[end:]...)
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return strings.Join(lines, "\n")
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.View()
	}

	innerWidth := a.viewport.Width - 2 // -2 for the borders
	if a.frameless() {
		innerWidth = a.viewport.Width
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return a.overlaySuggestions(body)
}

// renderTitleLine draws the viewport's top border carrying the view's title —
// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
// reader oriented where a top border would draw the top of a nonexistent box.
func (a *App) renderTitleLine() string {
	title := ""
	if view, ok := a.views[a.currentView]; ok {
		if hv, implements := view.(HeaderView); implements {
			title = hv.GetTitle()
		}
	}
	if a.frameless() {
		return theme.RenderTitledRule(title, a.width)
	}
	return theme.RenderBorderTitle(title, a.width)
}

// frameless reports whether the active view draws its own frames (see
// FramelessView). The default is framed.
func (a *App) frameless() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	fv, implements := view.(FramelessView)
	return implements && fv.Frameless()
}

// renderViewFooter returns the active view's footer, or "" when it has none.
func (a *App) renderViewFooter() string {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.RenderFooter(a.width)
		}
	}
	return ""
}

// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
// the border into one closed rectangle instead of two stacked boxes.
func replaceViewportBottomCorners(body string) string {
	lastNewline := strings.LastIndex(body, "\n")
	if lastNewline == -1 {
		return body
	}
	lastLine := body[lastNewline+1:]
	lastLine = strings.Replace(lastLine, "└", "├", 1)
	lastLine = strings.Replace(lastLine, "┘", "┤", 1)
	return body[:lastNewline+1] + lastLine
}
package app

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
)

// HeaderView is the interface each view must implement to provide the header data
type HeaderView interface {
	GetShortcuts() shortcut.Shortcuts
	GetTitle() string
	GetIcon() string
	GetHeaderInfo(context string) []shortcut.HeaderInfo
}

// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
type FooterView interface {
	GetFooterHeight() int          // current footer height in lines (0 if no footer)
	RenderFooter(width int) string // rendered footer content
}

// FramelessView is implemented by a view that draws its own frames and wants
// none around it. The default — framed — is the safe behavior: a view that
// does not implement this is framed like all the others, unlike HeaderView
// whose missing half silently renders an empty title.
//
// Only one view implements it (the dashboard), and that is deliberate: every
// other view frames a single object — a table, a form.
type FramelessView interface {
	Frameless() bool
}

// headerMinHeight is the fixed header height (without the command line).
const headerMinHeight = 7

// ASCII logo for the header
var logoLines = []string{
	`    ____            ____            __  `,
	`   / __ \___ _   __/ __ \___  _____/ /__`,
	`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
	` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
	`/_____/\___/|___/_____/\___/____/_/|_|  `,
}

const logoWidth = 40 // max width of a logo line

// paletteHintText is the permanent header hint that advertises the command palette
// (DEVDESK-109). It sits on the header's last row, flush right.
const paletteHintText = "ctrl+p Commands"

// renderHeader generates the header (fixed height) followed by the command line (1 line).
func (a *App) renderHeader() string {
	if view, ok := a.views[a.currentView]; ok {
		if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
			shortcuts := headerView.GetShortcuts()
			if a.commandMode {
				shortcuts = a.commandLineShortcuts()
			}
			info := headerView.GetHeaderInfo(a.currentContext)

			header := renderHeaderContent(info, shortcuts, a.width)

			pad := theme.Bg(" ")
			var cmdLine string
			if a.commandMode {
				cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.commandInput.View()) + pad
			} else {
				cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render("❯") + pad
			}

			// A blank line under the command line keeps it from touching the title rule.
			return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine + "\n" + theme.EmptyLineBg(a.width)
		}
	}

	return ""
}

// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
	// Two padding cells are the minimum a row can hold; below that the header
	// is blank rather than wider than the window.
	if width < 2 {
		return strings.Join(blankHeaderRows(width), "\n")
	}
	innerWidth := width - 2 // 1 padding each side

	// Column widths
	col1Width := innerWidth / 4
	col3Width := logoWidth
	// The logo column is fixed-width: drop it when it cannot sit next to the
	// info column, rather than pushing every row past the window (Rule 108).
	if innerWidth < col1Width+logoWidth {
		col3Width = 0
	}
	col2Width := innerWidth - col1Width - col3Width
	if col2Width < 0 {
		col2Width = 0
	}

	// Build column 1: key-value info lines
	col1Lines := buildInfoLines(info, col1Width)

	// Build column 2: shortcuts
	col2Lines := buildShortcutLines(shortcuts, col2Width)

	// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
	var col3Lines []string
	if col3Width > 0 {
		col3Lines = buildLogoLines(col3Width)
	}

	// Assemble rows
	rows := make([]string, headerMinHeight)
	for i := 0; i < headerMinHeight; i++ {
		c1 := ""
		if i < len(col1Lines) {
			c1 = col1Lines[i]
		}
		c2 := ""
		if i < len(col2Lines) {
			c2 = col2Lines[i]
		}
		c3 := ""
		if i < len(col3Lines) {
			c3 = col3Lines[i]
		}

		pad := theme.Bg(" ")
		if i == headerMinHeight-1 {
			// The hint takes the right end of the shortcut and logo columns.
			rows[i] = pad + theme.PadWithBg(c1, col1Width) + withPaletteHint(c2, col2Width+col3Width, col2Width) + pad
			continue
		}
		row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
		rows[i] = row
	}

	return strings.Join(rows, "\n")
}

// withPaletteHint returns a line of exactly width cells: shortcuts on the left,
// the palette hint flush right. The shortcuts are clipped to maxShortcuts cells
// and to what the hint leaves free; ansi.Truncate cuts on cell boundaries and
// never inside an escape sequence.
func withPaletteHint(shortcuts string, width, maxShortcuts int) string {
	hint := ansi.Truncate(theme.ShortcutHintStyle.Render(paletteHintText), width, "")
	free := min(maxShortcuts, width-lipgloss.Width(hint)-1)
	if free < 0 {
		free = 0
	}
	left := ansi.Truncate(shortcuts, free, "")
	gap := width - lipgloss.Width(left) - lipgloss.Width(hint)
	return left + theme.EmptyLineBg(gap) + hint
}

// blankHeaderRows returns headerMinHeight background-filled rows of the given width.
func blankHeaderRows(width int) []string {
	rows := make([]string, headerMinHeight)
	for i := range rows {
		rows[i] = theme.EmptyLineBg(width)
	}
	return rows
}

// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key.
// Lines wider than col1Width are clipped, so a narrow column never overflows into the next one.
func buildInfoLines(info []shortcut.HeaderInfo, col1Width int) []string {
	// Find max key length for alignment
	maxKeyLen := 0
	for _, h := range info {
		if len(h.Key) > maxKeyLen {
			maxKeyLen = len(h.Key)
		}
	}

	lines := make([]string, headerMinHeight)
	for i := 0; i < headerMinHeight; i++ {
		if i < len(info) {
			// Pad key to maxKeyLen so all ": " align
			paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
			label := theme.HeaderKeyStyle.Render(paddedKey + ": ")

			value := info[i].Value
			if info[i].Style.GetForeground() != lipgloss.Color("") {
				value = info[i].Style.Background(theme.ColorBackground).Render(value)
			} else {
				value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
			}

			lines[i] = label + value
			if col1Width > 0 {
				// MaxWidth truncates on rune boundaries and keeps escape sequences intact.
				lines[i] = lipgloss.NewStyle().MaxWidth(col1Width).Render(lines[i])
			} else {
				// No room at all: show nothing rather than overflow.
				lines[i] = ""
			}
		} else {
			lines[i] = ""
		}
	}
	return lines
}

// buildShortcutLines builds the shortcut lines for column 2
func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
	// A column with no width shows no shortcut: PadWithBg returns a long line
	// untouched, so anything rendered here would spill past the window.
	if len(shortcuts) == 0 || col2Width <= 0 {
		lines := make([]string, headerMinHeight)
		for i := range lines {
			lines[i] = ""
		}
		return lines
	}

	// Split shortcuts into columns of maxLine items
	columns := splitArrayIntoChunks(shortcuts, headerMinHeight)

	// Get rendered lines for each column
	var allColumnLines [][]string
	for i, col := range columns {
		minH := 0
		if i == 0 {
			minH = headerMinHeight
		}
		allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
	}

	// Normalize heights
	for i := range allColumnLines {
		for len(allColumnLines[i]) < headerMinHeight {
			allColumnLines[i] = append(allColumnLines[i], "")
		}
	}

	// Calculate column widths
	colWidths := make([]int, len(allColumnLines))
	for ci, colLines := range allColumnLines {
		for _, line := range colLines {
			if w := lipgloss.Width(line); w > colWidths[ci] {
				colWidths[ci] = w
			}
		}
	}

	sep := "  "
	sepRendered := theme.Bg(sep)

	// Build each row
	result := make([]string, headerMinHeight)
	for row := 0; row < headerMinHeight; row++ {
		var line string
		for ci, colLines := range allColumnLines {
			if ci > 0 {
				line += sepRendered
			}
			if row < len(colLines) {
				line += theme.PadWithBg(colLines[row], colWidths[ci])
			} else {
				line += theme.EmptyLineBg(colWidths[ci])
			}
		}
		// Clip to the column. PadWithBg cannot do this — it pads a short line and
		// returns a long one untouched — and a plain slice would cut an escape
		// sequence in half, which is the hazard Rule 122 is about. MaxWidth
		// truncates on rune boundaries and leaves the sequences intact.
		if col2Width > 0 {
			line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
		}
		result[row] = line
	}

	return result
}

// buildLogoLines builds the logo lines for column 3, vertically centered
func buildLogoLines(col3Width int) []string {
	logoStyle := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorPrimary).
		Bold(true)

	lines := make([]string, headerMinHeight)
	// 5 logo lines in 7 header lines → 1 empty line top and bottom
	offset := 1
	for i := 0; i < headerMinHeight; i++ {
		logoIdx := i - offset
		if logoIdx >= 0 && logoIdx < len(logoLines) {
			lines[i] = theme.PadWithBg(logoStyle.Render(logoLines[logoIdx]), col3Width)
		} else {
			lines[i] = theme.EmptyLineBg(col3Width)
		}
	}
	return lines
}

// renderShortcutsColumnLines renders a column of shortcuts as individual lines padded to the same width with background.
func renderShortcutsColumnLines(shortcuts shortcut.Shortcuts, minHeight int) []string {
	if len(shortcuts) == 0 {
		return nil
	}

	lines := shortcuts.ToStrings()

	// Find max width for uniform padding
	maxWidth := 0
	for _, line := range lines {
		if w := lipgloss.Width(line); w > maxWidth {
			maxWidth = w
		}
	}

	// Pad each line to the same width with background
	var result []string
	for _, line := range lines {
		result = append(result, theme.PadWithBg(line, maxWidth))
	}

	// Add empty lines if minHeight required
	for len(result) < minHeight {
		result = append(result, theme.EmptyLineBg(maxWidth))
	}

