// Init initializes the application
func (a *App) Init() tea.Cmd {
	// Note: resize() is already called in newWithSize() to initialize the dimensions
	cmds := []tea.Cmd{a.tryAutoLogin(), a.startMCPCmd(), a.restoreForwardsCmd(), a.detectScanTools()}

	if view, ok := a.views[a.currentView]; ok {
		cmds = append(cmds, view.Init())
	}

	return tea.Batch(cmds...)
}

// requestResize asks for a fresh layout at the current size. Every handler that
// changes what the window holds returns one, because the viewport height is
// budgeted against the header and the active view's footer.
func (a *App) requestResize() tea.Cmd {
	return func() tea.Msg {
		return tea.WindowSizeMsg{Width: a.width, Height: a.height}
	}
}

// resize lays out the window. It **iterates**, and that is necessary: the
// footer height is asked of the view (Rule 124), but a view whose footer
// depends on its own size — the dashboard hides its tab line once only one
// remains — answers based on the size it had *before*. A single pass would
// therefore leave it off by one line until the next resize.
// Two passes are enough: the second queries a view that now knows its size.
func (a *App) resize(width, height int) {
	a.width = width
	a.height = height
	defer a.keepHighlightVisible()

	const passes = 2
	for range passes {
		if !a.layoutOnce(width, height) {
			return
		}
	}
}

// layoutOnce sizes the viewport against the active view's footer and hands the
// view its content height. It returns true when the footer height changed
// along the way, i.e. when a second pass says something different.
func (a *App) layoutOnce(width, height int) (changed bool) {
	// Rule 124: footer height is deducted from the viewport (tabs + optional info line)
	footerHeight := a.getFooterHeight()
	a.lastFooterHeight = footerHeight

	headerHeight := lipgloss.Height(a.renderHeader())
	availableHeight := height - headerHeight - footerHeight
	a.viewport.Width = width
	a.viewport.Height = availableHeight - 1 // -1 for the custom title border line

	// Propagate to the active view. The viewport has 1 border (bottom only),
	// the view must know the inner height. A frameless view has none and
	// reclaims the line.
	viewportBorderHeight := 1
	a.viewport.Style = viewportStyle()
	if a.frameless() {
		viewportBorderHeight = 0
		a.viewport.Style = framelessViewportStyle()
	}
	contentHeight := max((availableHeight-1)-viewportBorderHeight, 1)
	if view, ok := a.views[a.currentView]; ok {
		updatedView, _ := view.Update(tea.WindowSizeMsg{Width: width, Height: contentHeight})
		a.views[a.currentView] = updatedView
	}

	return a.getFooterHeight() != footerHeight
}

// getFooterHeight returns the current footer height for the active view.
func (a *App) getFooterHeight() int {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.GetFooterHeight()
		}
	}
	return 0
}

// reinitializeViews drops every view so they are rebuilt against the current
// config, and returns the init cmd for the one on screen.
func (a *App) reinitializeViews() tea.Cmd {
	log.Printf("Reinitializing views with new config")
	a.views = make(map[command.ViewType]tea.Model)
	a.createView(a.currentView)

	var initCmd tea.Cmd
	if view, ok := a.views[a.currentView]; ok {
		initCmd = view.Init()
	}
	log.Printf("Views reinitialized successfully")
	return initCmd
}

func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.KeyMsg:
		return a.handleKeyMsg(msg)

	// ── Contexts and themes ──────────────────────────────────────────────
	case configuration.ConfigSavedMsg:
		return a.handleConfigSaved(msg)

	case contextNamesLoadedMsg:
		return a.handleContextNamesLoaded(msg)

	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)
	case tea.KeyShiftTab:
		return a, nil
	case tea.KeyUp:
		a.moveHighlight(-1)
		return a, nil
	case tea.KeyDown:
		a.moveHighlight(1)
		return a, nil
	case tea.KeyEnter:
		return a.runCommand()
	}
	return a.handleCommandInput(msg)
}

// handleCommandInput feeds an ordinary key to the input and ranks the registry
// again for the new text.
func (a *App) handleCommandInput(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	before := a.commandInput.Value()
	a.commandInput, cmd = a.commandInput.Update(msg)
	if a.commandInput.Value() != before {
		a.refreshSuggestions()
	}
	return a, cmd
}

// closeCommandLine leaves command mode and asks for the re-layout that gives
// the row back to the inactive prompt. The list goes with the line.
func (a *App) closeCommandLine() tea.Cmd {
	a.commandMode = false
	a.commandInput.Blur()
	a.resetSuggestions()
	return a.requestResize()
}

// runnableText is the single availability question for enter, read by the
// header (to grey it) and by runCommand (to refuse). With a list drawn it is
// the highlighted row's name. At the argument stage, or with no list drawn
// (too short a viewport), it is the text as typed: a prefix such as "co" is
// not a name and runs nothing, but an empty line has nothing to run.
func (a *App) runnableText() (string, bool) {
	if a.suggestions.Stage != command.StageArgument && a.listVisible() > 0 {
		entry, ok := a.highlightedEntry()
		return entry.Name, ok
	}
	input := a.commandInput.Value()
	return input, strings.TrimSpace(input) != ""
}

// runCommand executes the highlighted row, or at the argument stage the text
// as typed. With nothing to run it says so on the list's bottom rule and
// leaves the line open.
func (a *App) runCommand() (tea.Model, tea.Cmd) {
	input, ok := a.runnableText()
	if !ok {
		// Only a drawn list has a rule to carry the notice; without one the
		// refusal is silent, a documented exception to Rule 130.
		if a.listVisible() > 0 {
			a.sugNotice = a.nothingToRunNotice()
		}
		return a, nil
	}

	cmd := command.ParseCommand(input)

	switch cmd.Type {
	case command.CommandQuit:
		a.resetSuggestions()
		return a, tea.Quit

	case command.CommandView:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetSuggestions()
		a.resetSelectionModeFor(cmd.View)
		return a, a.switchView(cmd.View)

	case command.CommandContext:
		return a.runContext(cmd.Args)
	}

	return a, nil
}

// resetSelectionModeFor takes a view out of selection mode before switching to
// it, by dropping it so it is rebuilt normally.
//
// Only the workspaces view is lent now. The images view was the other one — the
// security form borrowed it to pick a scan target — and it could not simply be
// dropped, because it holds scan results worth keeping; it took a
// ResetSelectionMsg instead. That whole path went with the form (phase 3).
package app

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/contextcmd"
	"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// argStage reports whether the list shows argument rows: the :ctx command at
// its argument stage. Other commands keep the single command row.
func (a *App) argStage() bool {
	return a.suggestions.Stage == command.StageArgument &&
		command.ParseCommand(a.commandInput.Value()).Type == command.CommandContext
}

// listRowCount is how many rows the list holds at the current stage.
func (a *App) listRowCount() int {
	if a.argStage() {
		return len(a.suggestions.Args)
	}
	return len(a.suggestions.Entries)
}

// ctxArgText is the text typed after the command word, trimmed on the left.
func (a *App) ctxArgText() string {
	_, rest, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
	return strings.TrimLeft(rest, " ")
}

// defaultArgCursor picks the row highlighted when the argument list is drawn:
// the exact match; else the only match when contextcmd accepts it as a valid
// name; else none.
func (a *App) defaultArgCursor() int {
	args := a.suggestions.Args
	prefix := a.ctxArgText()
	if prefix == "" || !a.suggestions.ArgsReady {
		return -1
	}
	for i, s := range args {
		if s.Value == prefix {
			return i
		}
	}
	if len(args) != 1 {
		return -1
	}
	if !contextcmd.ValidName(prefix) {
		return -1
	}
	return 0
}

// argHeading is the rule's label at the argument stage: contexts shown out of
// all contexts, the reserved words not counted.
// Package cmdsuggest renders the command-suggestion list shown under the
// command line (DEVDESK-89). Rendering is pure: state in, lines out.
package cmdsuggest

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// MaxVisibleRows is the ceiling on suggestion rows shown at once.
const MaxVisibleRows = 8

// Row is one suggestion; Current marks the view that is open now.
type Row struct {
	Entry   command.Entry
	Current bool
	// Arg, when non-nil, makes this an argument row: Entry is ignored.
	Arg *command.ArgSuggestion
}

// Frame selects the corners of the bottom rule.
type Frame int

const (
	// FrameJoined draws ├─┤ (the list sits above more viewport content).
	FrameJoined Frame = iota
	// FrameClosed draws └─┘.
	FrameClosed
)

// Input is everything Render needs.
type Input struct {
	Rows   []Row
	Total  int
	Query  string
	Cursor int // -1 means no highlighted row
	Offset int
	Notice string
	// Heading replaces the "N of M" count in the filet (argument stage).
	Heading string
	// Empty is the message shown when there are no rows and Loading is false.
	Empty string
	// Loading shows "Loading contexts…" in place of the rows.
	Loading bool
	Width   int
	Visible int
	Frame   Frame
}

// Layout holds column widths in cells.
type Layout struct{ Marker, Name, Alias, Desc int }

