// a theme applied at run time. The prompt is the border colour, the text is
// ColorText, every segment carries an explicit background.
func paletteInputView(in textinput.Model, frameWidth int) string {
	bg := lipgloss.NewStyle().Background(theme.ColorBackground)
	in.Prompt = paletteInputPrompt
	in.PromptStyle = bg.Foreground(theme.ColorPaletteBorder)
