func TestCtxArgumentListShowsContextsThenReservedWords(t *testing.T) {
	a := argRouter(t)
	ctxOpen(t, a, "ctx ")

	rows := listRows(t, a)
	if len(rows) != 5 {
		t.Fatalf("%d rows, want 5 (3 contexts, -, new): %q", len(rows), rows)
	}
	for i, want := range []string{"default (current)", "web", "work", "-", "new"} {
		if !strings.Contains(rows[i], want) {
			t.Errorf("row %d = %q, want it to contain %q", i, rows[i], want)
		}
			typeCommand(t, a, "zzz")
			press(t, a, "enter")

			if !a.commandMode || a.currentView != command.ViewDashboard {
				t.Errorf("commandMode=%v view=%s: an unknown command did not leave the palette open", a.commandMode, a.currentView)
			}
			if got, want := filet(t, a), theme.IconWarning+` "zzz" is not a view or a command`; !strings.Contains(got, want) {
				t.Errorf("rule %q lacks %q", got, want)
			}
		})
	}
}

